arguments.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
        : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                Ratings = [5, 4, 5, 4]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale, then quickly stir in egg mixture off heat.\n5. Serve immediately with extra cheese and pepper.",
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt and spices for at least 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pot.\n4. Add tomato sauce and spices; simmer 15 minutes.\n5. Cut chicken into pieces and add to sauce.\n6. Stir in cream and simmer 10 more minutes.",
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nGarlic",
                Steps = "1. Soak rice noodles in warm water for 20 minutes; drain.\n2. Mix tamarind paste, fish sauce, and sugar for the sauce.\n3. Stir-fry tofu until golden, set aside.\n4. Sauté garlic, add noodles and sauce.\n5. Toss in tofu, bean sprouts, and green onions.\n6. Serve with crushed peanuts and lime wedge.",
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nTaco seasoning\nOnion",
                Steps = "1. Brown ground beef with diced onion.\n2. Add taco seasoning and water; simmer until thickened.\n3. Warm taco shells in the oven.\n4. Fill shells with beef, lettuce, tomato, cheese, and sour cream.",
                Ratings = [4, 3, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nOnion\nTomato\nJalapeño\nSalt\nGarlic",
                Steps = "1. Halve avocados, remove pits, and scoop into a bowl.\n2. Mash to desired consistency.\n3. Mix in diced onion, tomato, jalapeño, cilantro, and garlic.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
                Ratings = [5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla\nFlour\nBaking soda\nSalt\nChocolate chips",
                Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt; stir into wet ingredients.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheet.\n6. Bake at 375°F (190°C) for 9-11 minutes.",
                Ratings = [5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Miso Soup", Category = "Asian",
                Ingredients = "Dashi stock\nMiso paste\nTofu\nWakame seaweed\nGreen onions",
                Steps = "1. Bring dashi stock to a simmer.\n2. Add wakame and tofu cubes.\n3. Remove from heat; dissolve miso paste into broth.\n4. Garnish with sliced green onions.\n5. Serve immediately — do not boil after adding miso.",
                Ratings = [4, 4, 3]
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public Recipe Submit(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
