@page "/recipe/{RecipeId:int}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <h4>Instructions</h4>
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </div>
    </div>

    <hr />

    <div class="mt-3">
        <h4>Rate this Recipe</h4>
        @if (recipe.AverageRating > 0)
        {
            <p>Average: ⭐ @recipe.AverageRating / 5 (@recipe.Ratings.Count ratings)</p>
        }
        <StarRating RecipeId="recipe.Id" OnRated="HandleRated" />
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetById(RecipeId);
    }

    private void HandleRated()
    {
        recipe = RecipeService.GetById(RecipeId);
    }
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-flex align-items-center" role="group" aria-label="Star rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button type="button"
                class="btn btn-link fs-4 p-0 me-1 text-decoration-none"
                style="cursor: pointer;"
                title="Rate @star star@(star > 1 ? "s" : "")"
                @onclick="() => SubmitRating(star)">
            @(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "★" : "☆")
        </button>
    }
    @if (selectedStar > 0)
    {
        <span class="ms-2 text-success">You rated @selectedStar star@(selectedStar > 1 ? "s" : "")!</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }
    [Parameter] public EventCallback OnRated { get; set; }

    private int selectedStar;
    private int hoveredStar;

    private async Task SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        await OnRated.InvokeAsync();
    }
}

